package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// The message wiring blocks. The flat topic/contract/pubsub keys above
	// are superseded by these: a scaffold carries either a subscribe block
	// (what the component consumes, from the registry or a producing
	// sibling) or a publishes block (what it declares). Both shapes are
	// read everywhere; writers emit only the blocks.
	KeySubscribe     = "subscribe"
	KeyPublishes     = "publishes"
	KeyMessage       = "message"
	KeyDataschema    = "dataschema"
	KeyDataschemaURL = "dataschemaurl"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

// The message wiring blocks. A subscribe block names the message the
// component consumes; without pubsub/topic it is an internal subscription
// whose channel assembly resolves from the producing component. With the
// snapshot fields it is an external subscription — the registry is never
// contacted again for it.
//
// A publishes block declares what its component produces; internal and
// registry-resolved publications differ only in which fields they carry,
// and PublishesBlock's doc comment owns that split.
type SubscribeBlock struct {
	Message       string
	Pubsub        string
	Topic         string
	Dataschema    string
	DataschemaURL string
}

// PublishesBlock is a producer's message declaration. A registry-resolved
// publish carries the full channel snapshot (pubsub, topic) and the schema
// pin; a producer-declared internal publish carries only the message.
// Contract is the .NET shared-project type name, carried during the
// transition while host templates render Topics.cs from it; it is not the
// CloudEvents type.
// Contract is the .NET shared-project type name, carried during the
// transition while host templates render Topics.cs from it; it is not the
// CloudEvents type.
type PublishesBlock struct {
	Message       string
	Contract      string
	Dataschema    string
	DataschemaURL string
	Pubsub        string
	Topic         string
}

// External reports whether the declaration carries its own channel
// snapshot. External publications assemble their channel from the record
// alone; internal publications default to the system pubsub on a topic
// named after the message.
func (b *PublishesBlock) External() bool { return b.Topic != "" }

// External reports whether the subscription carries its own channel
// snapshot. External subscriptions assemble without a producer and without
// touching the registry.
func (b *SubscribeBlock) External() bool { return b.Topic != "" }

// HasSubscribeValue reports whether values carry a subscribe block. Block
// presence wins over the legacy flat keys wherever both appear — the dual
// read is a fallback, never a merge.
func HasSubscribeValue(values map[string]any) bool {
	_, ok := values[KeySubscribe]
	return ok
}

// HasPublishesValue reports whether values carry a publishes block.
func HasPublishesValue(values map[string]any) bool {
	_, ok := values[KeyPublishes]
	return ok
}

// HasMessageBlocks reports whether values use the block wiring shape at
// all. Assembly and facts treat such records as block-shaped and ignore
// their legacy flat keys.
func HasMessageBlocks(values map[string]any) bool {
	return HasSubscribeValue(values) || HasPublishesValue(values)
}

// blockMap reads one block value as the map the writers produce. The
// strict regime applies: a present block must be an object, so a mistyped
// block is an error naming the record and the block, never a silent skip.
func blockMap(e ScaffoldEntry, block string) (map[string]any, error) {
	v, ok := e.Values[block]
	if !ok {
		return nil, nil // absent is not an error; the caller decides
	}
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.%s has type %T, expected object", recordPath(e), block, v)
	}
	return m, nil
}

// blockString reads a strict non-empty string field out of a block: mistyped
// or empty names the record and the full key path.
func blockString(e ScaffoldEntry, block, key string) (string, error) {
	m, err := blockMap(e, block)
	if err != nil {
		return "", err
	}
	v, ok := m[key]
	if !ok {
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s.%s has type %T, expected string", recordPath(e), block, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s.%s is empty", recordPath(e), block, key)
	}
	return s, nil
}

// recordPath names the record in error messages, matching RecordValue.
func recordPath(e ScaffoldEntry) string {
	return filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
}

// ReadSubscribeBlock strictly reads the subscribe block. The message name
// is required; the snapshot fields are each required to be non-empty
// strings when present. A record with the block and empty message is a
// broken record, not a wireless one.
func ReadSubscribeBlock(e ScaffoldEntry) (*SubscribeBlock, error) {
	if !HasSubscribeValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeySubscribe, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeySubscribe, KeyMessage)
	}
	b := &SubscribeBlock{Message: message}
	for _, f := range []struct {
		key string
		dst *string
	}{
		{KeyPubsub, &b.Pubsub},
		{KeyTopic, &b.Topic},
		{KeyDataschema, &b.Dataschema},
		{KeyDataschemaURL, &b.DataschemaURL},
	} {
		s, err := blockString(e, KeySubscribe, f.key)
		if err != nil {
			return nil, err
		}
		*f.dst = s
	}
	return b, nil
}

// ReadPublishesBlock strictly reads the publishes block. The message name
// is required; contract, dataschema, and the channel snapshot stay optional
// for internal declarations. The pubsub/topic pair is validated by system
// assembly, not here — the block reader stays a shape reader, matching how
// the subscribe branch splits concerns.
func ReadPublishesBlock(e ScaffoldEntry) (*PublishesBlock, error) {
	if !HasPublishesValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeyPublishes, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeyPublishes, KeyMessage)
	}
	b := &PublishesBlock{Message: message}
	for _, f := range []struct {
		key string
		dst *string
	}{
		{KeyContract, &b.Contract},
		{KeyDataschema, &b.Dataschema},
		{KeyDataschemaURL, &b.DataschemaURL},
		{KeyPubsub, &b.Pubsub},
		{KeyTopic, &b.Topic},
	} {
		s, err := blockString(e, KeyPublishes, f.key)
		if err != nil {
			return nil, err
		}
		*f.dst = s
	}
	return b, nil
}

// SubscribeBlockValue renders the block as the values-map entry writers
// emit. Writers never add the legacy flat keys alongside it.
func SubscribeBlockValue(b *SubscribeBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	if b.Pubsub != "" {
		m[KeyPubsub] = b.Pubsub
	}
	if b.Topic != "" {
		m[KeyTopic] = b.Topic
	}
	if b.Dataschema != "" {
		m[KeyDataschema] = b.Dataschema
	}
	if b.DataschemaURL != "" {
		m[KeyDataschemaURL] = b.DataschemaURL
	}
	return m
}

// PublishesBlockValue renders a publishes declaration as the values-map
// entry writers emit.
func PublishesBlockValue(b *PublishesBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	for _, f := range []struct {
		key   string
		value string
	}{
		{KeyContract, b.Contract},
		{KeyDataschema, b.Dataschema},
		{KeyDataschemaURL, b.DataschemaURL},
		{KeyPubsub, b.Pubsub},
		{KeyTopic, b.Topic},
	} {
		if f.value != "" {
			m[f.key] = f.value
		}
	}
	return m
}

//go:build e2e

package system

// Renders the real system-host template from a local intropy-templates
// checkout through the production engine (values resolution, spec.files,
// conditional dependencies, skeleton rendering). Run with:
//
//	INTROPY_TEMPLATES_DIR=~/dev/intropy/tooling/intropy-templates go test -tags e2e ./internal/system/ -run TestRealSystemHost -v

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	texttemplate "text/template"

	"github.com/Masterminds/sprig/v3"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

func templatesDir(t *testing.T) string {
	t.Helper()
	dir := os.Getenv("INTROPY_TEMPLATES_DIR")
	if dir == "" {
		t.Skip("INTROPY_TEMPLATES_DIR not set")
	}
	return dir
}

func renderRealHost(t *testing.T, payload map[string]any) (outDir, parent string) {
	t.Helper()
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, "system-host", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	values, err := template.Resolve(tmpl, nil, nil, payload, nil)
	if err != nil {
		t.Fatal(err)
	}
	parent = t.TempDir()
	outDir = filepath.Join(parent, "order-flow")
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := template.RenderFiltered(filepath.Join(lib, "system-host", "skeleton"), outDir, values, tmpl.Spec.Files); err != nil {
		t.Fatalf("render: %v", err)
	}
	// The dependency half of Create, unexported — replicate the when check
	// for the one entry the host declares.
	for _, dep := range tmpl.Spec.Dependencies {
		_ = dep
	}
	return outDir, parent
}

func TestRealSystemHostTransactionalOnly(t *testing.T) {
	outDir, _ := renderRealHost(t, map[string]any{
		"name":       "trans",
		"topics":     []any{},
		"ports":      []any{map[string]any{"name": "erp-source"}, map[string]any{"name": "erp-destination"}},
		"components": []any{map[string]any{"appId": "erp-sync", "kind": "transactional-integration", "fromPort": "erp-source", "toPort": "erp-destination"}},
	})
	if _, err := os.Stat(filepath.Join(outDir, "Topics.cs")); !os.IsNotExist(err) {
		t.Errorf("Topics.cs should not render, err = %v", err)
	}
	csproj, _ := os.ReadFile(filepath.Join(outDir, "Trans.SystemHost.csproj"))
	if strings.Contains(string(csproj), "ProjectReference") {
		t.Errorf("csproj should have no contracts reference:\n%s", csproj)
	}
	system, err := os.ReadFile(filepath.Join(outDir, "TransSystem.cs"))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`builder.AddTransactionalIntegration("erp-sync")`, ".From(Ports.ErpSource)", ".To(Ports.ErpDestination)"} {
		if !strings.Contains(string(system), want) {
			t.Errorf("TransSystem.cs missing %q:\n%s", want, system)
		}
	}
	ports, err := os.ReadFile(filepath.Join(outDir, "Ports.cs"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(ports), "PortRef ErpSource") {
		t.Errorf("Ports.cs:\n%s", ports)
	}
	dev, err := os.ReadFile(filepath.Join(outDir, "TransDevelopment.cs"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(dev), `development.Files(Ports.ErpSource).RootPath("./test/erp-source");`) {
		t.Errorf("TransDevelopment.cs:\n%s", dev)
	}
}

func TestRealSystemHostTopicSystemWithContracts(t *testing.T) {
	outDir, _ := renderRealHost(t, map[string]any{
		"name":   "order-flow",
		"topics": []any{map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order"}},
		"ports":  []any{map[string]any{"name": "order-extractor-source"}, map[string]any{"name": "order-loader-destination"}},
		"components": []any{
			map[string]any{"appId": "order-extractor", "kind": "extractor", "topic": map[string]any{"pubsub": "pubsub", "name": "orders"}, "port": "order-extractor-source"},
			map[string]any{"appId": "order-loader", "kind": "loader", "topic": map[string]any{"pubsub": "pubsub", "name": "orders"}, "port": "order-loader-destination"},
		},
		"sharedContracts": map[string]any{"name": "Contracts", "include": "../Contracts/Contracts.csproj"},
	})
	topics, err := os.ReadFile(filepath.Join(outDir, "Topics.cs"))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"using Contracts;", `TopicRef<Order> Orders = TopicRef<Order>.Define("pubsub", "orders");`} {
		if !strings.Contains(string(topics), want) {
			t.Errorf("Topics.cs missing %q:\n%s", want, topics)
		}
	}
	system, err := os.ReadFile(filepath.Join(outDir, "OrderFlowSystem.cs"))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{".From(Ports.OrderExtractorSource)", ".Publishes(Topics.Orders)", ".Subscribes(Topics.Orders)", ".To(Ports.OrderLoaderDestination)"} {
		if !strings.Contains(string(system), want) {
			t.Errorf("OrderFlowSystem.cs missing %q:\n%s", want, system)
		}
	}
	csproj, _ := os.ReadFile(filepath.Join(outDir, "OrderFlow.SystemHost.csproj"))
	if !strings.Contains(string(csproj), `<ProjectReference Include="../Contracts/Contracts.csproj"`) {
		t.Errorf("csproj:\n%s", csproj)
	}
}

func TestRealSystemHostFieldCollisionFails(t *testing.T) {
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, "system-host", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	values, err := template.Resolve(tmpl, nil, nil, map[string]any{
		"name": "collide",
		"topics": []any{
			map[string]any{"pubsub": "pubsub", "name": "order-events", "contract": "Order"},
			map[string]any{"pubsub": "pubsub", "name": "order.events", "contract": "Order"},
		},
		"ports":           []any{},
		"components":      []any{},
		"sharedContracts": map[string]any{"name": "Contracts", "include": "../Contracts/Contracts.csproj"},
	}, nil)
	if err != nil {
		t.Fatal(err)
	}
	err = template.RenderFiltered(filepath.Join(lib, "system-host", "skeleton"), t.TempDir(), values, tmpl.Spec.Files)
	if err == nil || !strings.Contains(err.Error(), "both derive the Topics.cs field OrderEvents") {
		t.Fatalf("err = %v, want a field-collision failure naming both topics", err)
	}
}

func TestRealSystemHostDependencyWhen(t *testing.T) {
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, "system-host", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if len(tmpl.Spec.Dependencies) != 2 {
		t.Fatalf("dependencies = %+v", tmpl.Spec.Dependencies)
	}
	dep := tmpl.Spec.Dependencies[0]
	if dep.Template != "shared-contracts" || dep.When == "" {
		t.Fatalf("dependency = %+v", dep)
	}
	seedDep := tmpl.Spec.Dependencies[1]
	if seedDep.Template != "testdata" || seedDep.When == "" {
		t.Fatalf("testdata dependency = %+v", seedDep)
	}

	// Evaluate the when expression against resolved payloads with the same
	// machinery the engine uses (sprig + missingkey=error).
	eval := func(payload map[string]any) string {
		values, err := template.Resolve(tmpl, nil, nil, payload, nil)
		if err != nil {
			t.Fatal(err)
		}
		tt, err := texttemplate.New("when").Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(dep.When)
		if err != nil {
			t.Fatal(err)
		}
		var sb strings.Builder
		if err := tt.Execute(&sb, values); err != nil {
			t.Fatal(err)
		}
		return sb.String()
	}

	topicsPayload := map[string]any{
		"name":       "order-flow",
		"topics":     []any{map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order"}},
		"ports":      []any{},
		"components": []any{},
	}
	if got := eval(topicsPayload); got == "false" || got == "" {
		t.Errorf("topic system without contracts should render the dependency, when = %q", got)
	}
	withContracts := map[string]any{
		"name":            "order-flow",
		"topics":          []any{map[string]any{"pubsub": "pubsub", "name": "orders", "contract": "Order"}},
		"ports":           []any{},
		"components":      []any{},
		"sharedContracts": map[string]any{"name": "Contracts", "include": "../Contracts/Contracts.csproj"},
	}
	if got := eval(withContracts); got != "false" {
		t.Errorf("existing contracts should skip the dependency, when = %q", got)
	}
	noTopics := map[string]any{"name": "trans", "topics": []any{}, "ports": []any{}, "components": []any{}}
	if got := eval(noTopics); got != "false" {
		t.Errorf("topic-free system should skip the dependency, when = %q", got)
	}

	// The dependency's contract value renders from the first topic, and the
	// dependency template itself loads from the same checkout.
	values, err := template.Resolve(tmpl, nil, nil, topicsPayload, nil)
	if err != nil {
		t.Fatal(err)
	}
	ct, err := texttemplate.New("c").Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(dep.Values["contract"])
	if err != nil {
		t.Fatal(err)
	}
	var cs strings.Builder
	if err := ct.Execute(&cs, values); err != nil {
		t.Fatal(err)
	}
	if cs.String() != "Order" {
		t.Errorf("dependency contract = %q, want Order", cs.String())
	}
	if _, err := template.LoadTemplate(filepath.Join(lib, dep.Template, "template.yaml")); err != nil {
		t.Fatalf("dependency template: %v", err)
	}

	// The testdata dependency renders for a port-bearing system and skips a
	// port-less one; its port value comes from the first declared port.
	evalSeed := func(payload map[string]any) string {
		values, err := template.Resolve(tmpl, nil, nil, payload, nil)
		if err != nil {
			t.Fatal(err)
		}
		tt, err := texttemplate.New("when").Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(seedDep.When)
		if err != nil {
			t.Fatal(err)
		}
		var sb strings.Builder
		if err := tt.Execute(&sb, values); err != nil {
			t.Fatal(err)
		}
		return sb.String()
	}
	portsPayload := map[string]any{
		"name":       "order-flow",
		"topics":     []any{},
		"ports":      []any{map[string]any{"name": "order-extractor-source"}},
		"components": []any{},
	}
	if got := evalSeed(portsPayload); got == "false" || got == "" {
		t.Errorf("port-bearing system should render the testdata dependency, when = %q", got)
	}
	if got := evalSeed(noTopics); got != "false" {
		t.Errorf("port-less system should skip the testdata dependency, when = %q", got)
	}
	seedValues, err := template.Resolve(tmpl, nil, nil, portsPayload, nil)
	if err != nil {
		t.Fatal(err)
	}
	pt, err := texttemplate.New("p").Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(seedDep.Values["port"])
	if err != nil {
		t.Fatal(err)
	}
	var ps strings.Builder
	if err := pt.Execute(&ps, seedValues); err != nil {
		t.Fatal(err)
	}
	if ps.String() != "order-extractor-source" {
		t.Errorf("testdata port = %q, want order-extractor-source", ps.String())
	}
	if _, err := template.LoadTemplate(filepath.Join(lib, seedDep.Template, "template.yaml")); err != nil {
		t.Fatalf("testdata dependency template: %v", err)
	}
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library. Zero values target the
	// official library at integrio-intropy/intropy-templates; the CLI sets
	// them from --template-repo, INTROPY_TEMPLATE_REPO, or templateRepo in
	// the config file.
	Owner string
	Repo  string

	// Source carries the fetch seams shared by every template-fetch path.
	// GitHubBaseURL redirects the latest-release API call in tests.
	Source SourceOptions

	// OnManifest, when set, runs after the manifest loads and before
	// values resolve, render, dependency processing, or the scaffold
	// record write. A non-nil error aborts the create. Callers use it for
	// gates that must run before any output is written.
	OnManifest func(*Template) error

	// Facts, when set, feeds prompt-time parameter suggestions: what the
	// workspace's scaffold records already declare (topics, contracts,
	// ports). Facts propose to the prompter; they never resolve a value on
	// their own, and a nil index resolves exactly as before.
	Facts *WorkspaceFacts

	// Subscribe, when set, is the pre-resolved registry wiring written into
	// the record's subscribe block — the value --subscribe produces. The
	// manifest must declare message parameters for it to apply; otherwise
	// the run fails with ErrNoMessageParameters before anything renders.
	// The block lands in values as the U3 shape and renders only in
	// templates that declare message parameters — the resolved block is
	// additive to the parameter set, never a replacement for one.
	Subscribe *SubscribeBlock

	// Publishes is Subscribe's producing-side counterpart: the
	// pre-resolved channel snapshot written into the record's publishes
	// block, the value --publishes produces. It carries the same gates —
	// message parameters, direction — and seeds the same message
	// parameters; contract stays a template parameter, never a product of
	// the resolution.
	Publishes *PublishesBlock

	// MessageRefs are registry message references offered as prompt
	// suggestions for the template's message parameters (next to the
	// workspace's own publishes declarations). Suggestion metadata only —
	// a ref becomes a value only through a confirmed prompt, --set, or
	// --subscribe.
	MessageRefs []string

	// MessageRefsLoader lazily loads MessageRefs after the manifest proves
	// the template has message parameters. Callers use it when fetching the
	// candidate pool has external cost.
	MessageRefsLoader func(context.Context) ([]string, error)
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
}

// sourceOpts projects the create options onto the shared fetch options. A
// Source that names its own Owner/Repo wins — it is the test seam.
func (o CreateOptions) sourceOpts() SourceOptions {
	s := o.Source
	s.Version = o.Version
	s.Stderr = o.Stderr
	s.UserAgent = o.UserAgent
	if s.Owner == "" && s.Repo == "" {
		s.Owner, s.Repo = libraryIdentity(o.Owner, o.Repo)
	}
	return s
}

// Create runs the full scaffold: resolve release, ensure the cached checkout,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	src, err := FetchSource(ctx, opts.sourceOpts())
	if err != nil {
		return err
	}
	tag := src.Version

	templateRoot, err := templateDir(src, src.Owner, src.Repo, opts.Template)
	if err != nil {
		return err
	}

	tmpl, values, err := prepareCreateTemplate(ctx, templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(filepath.Join(templateRoot, templateSkeletonDir), tmpl, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, src.Owner, src.Repo, tag, opts.Template)

	// Dependencies come from the same library checkout, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    src.Owner,
		repo:     src.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         src.Owner,
		Repo:          src.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, src, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

func prepareCreateTemplate(ctx context.Context, templateRoot string, opts CreateOptions) (*Template, map[string]any, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, err
	}
	if opts.OnManifest != nil {
		if err := opts.OnManifest(tmpl); err != nil {
			return nil, nil, err
		}
	}

	// Message-capable templates get the prompt-time candidate pool even on
	// runs without the registry: the ref list may be empty, but the
	// parameter registry still turns --subscribe hints and pick lists on.
	// The template's direction rides along so the pool, filtered for the
	// template's direction, and the wiring hint stay direction-aware.
	messageParams := tmpl.MessageParameters()
	if len(messageParams) > 0 && opts.Facts != nil {
		opts.Facts.SetMessageParameters(messageParams)
		opts.Facts.SetWiringDirection(MessageDirection(blockKindFromLabels(tmpl.Metadata.Labels)))
		refs := opts.MessageRefs
		if len(refs) == 0 && opts.MessageRefsLoader != nil {
			var err error
			refs, err = opts.MessageRefsLoader(ctx)
			if err != nil {
				// The pool is prompt-time advisory: a loader failure must
				// degrade to the workspace's own candidates, never fail a
				// create the records themselves would still allow. Explicit
				// message flags resolve separately and keep their hard
				// failure path.
				fmt.Fprintf(opts.Stderr, "warning: %v — message suggestions fall back to workspace messages only\n", err)
				refs = nil
			}
		}
		opts.Facts.AddMessageCandidates(refs)
	}
	if opts.Subscribe != nil && opts.Publishes != nil {
		return nil, nil, fmt.Errorf("template create: %w", ErrMessageFlagsExclusive)
	}
	// The message blocks land in SetValues alongside the seeds; a caller
	// that passes no sets still gets the block, so nil normalizes here —
	// the one intake point every message flag funnels through.
	if opts.SetValues == nil {
		opts.SetValues = map[string]any{}
	}
	if opts.Subscribe != nil {
		if len(messageParams) == 0 {
			return nil, nil, fmt.Errorf("template %q: %w\n--subscribe requires a template release whose manifest declares message parameters (label %s); check the pinned template version", tmpl.Metadata.Name, ErrNoMessageParameters, TemplateMessageParamsLabel)
		}
		if err := gateMessageDirection(tmpl, MessageDirectionSubscribe); err != nil {
			return nil, nil, err
		}
		if err := seedMessageParameters(tmpl.Metadata.Name, messageParams, opts.SetValues, "--subscribe", ErrSubscribeMessageConflict, opts.Subscribe.Message); err != nil {
			return nil, nil, err
		}
		opts.SetValues[KeySubscribe] = SubscribeBlockValue(opts.Subscribe)
	}
	if opts.Publishes != nil {
		if len(messageParams) == 0 {
			return nil, nil, fmt.Errorf("template %q: %w\n--publishes requires a template release whose manifest declares message parameters (label %s); check the pinned template version", tmpl.Metadata.Name, ErrNoMessageParameters, TemplateMessageParamsLabel)
		}
		if err := gateMessageDirection(tmpl, MessageDirectionPublish); err != nil {
			return nil, nil, err
		}
		if err := seedMessageParameters(tmpl.Metadata.Name, messageParams, opts.SetValues, "--publishes", ErrMessageParameterConflict, opts.Publishes.Message); err != nil {
			return nil, nil, err
		}
		opts.SetValues[KeyPublishes] = PublishesBlockValue(opts.Publishes)
	}

	prompter := selectPrompter(&opts)
	values, err := ResolveWith(tmpl, ResolveOptions{
		Facts:    opts.Facts,
		Files:    opts.Files,
		Stdin:    opts.Stdin,
		Sets:     opts.SetValues,
		Prompter: prompter,
		Notes:    opts.Stderr,
	})
	if err != nil {
		return nil, nil, err
	}
	return tmpl, values, nil
}

// renderCreateOutput renders an extracted skeleton into outputDir, honoring
// the manifest's spec.files rules. The caller passes the skeleton root
// itself (PrepareCreate has already verified it), so the missing-skeleton
// check lives next to the fetch that could produce it.
func renderCreateOutput(skelRoot string, tmpl *Template, templateName, outputDir string, force bool, values map[string]any) error {
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return RenderFiltered(skelRoot, outputDir, values, tmpl.Spec.Files)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, src *Source, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:     tmpl.Metadata.Name,
		Owner:        src.Owner,
		Repo:         src.Repo,
		Version:      src.Version,
		OutputDir:    absOut,
		Values:       values,
		Dependencies: deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// ValidateTemplateName reports whether name is safe to use as a template
// directory — the exported half of validateTemplateName for callers that
// resolve a library themselves (the dashboard's template endpoints) and need
// the same refusal before joining user input into a path.
func ValidateTemplateName(name string) error {
	return validateTemplateName(name)
}

// validateTemplateName rejects empty names and anything that could escape the
// library checkout root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

// ErrNoMessageParameters reports --subscribe or --publishes against a
// template whose manifest declares no message parameters. Callers map it
// to a usage error: the fault is in the requested combination, not the
// environment.
var ErrNoMessageParameters = errors.New("declares no message parameters")

// ErrSubscribeMessageConflict reports a message parameter value that does
// not match the registry message --subscribe resolved.
var ErrSubscribeMessageConflict = errors.New("message parameter conflicts with --subscribe")

// ErrMessageParameterConflict is the direction-neutral form of
// ErrSubscribeMessageConflict, reported when --publishes resolves a
// different message than a pre-set parameter value.
var ErrMessageParameterConflict = errors.New("message parameter conflicts with --publishes")

// ErrMessageDirection reports a message flag pointed at a template whose
// block kind wires messages the other way, or not at all. Callers map it
// to a usage error alongside ErrNoMessageParameters.
var ErrMessageDirection = errors.New("template does not wire messages in this direction")

// ErrMessageFlagsExclusive reports both message flags on one create — a
// programming-visible state (the CLI rejects the combination as a usage
// error before Create runs) guarded here so library callers cannot reach
// a record carrying both blocks.
var ErrMessageFlagsExclusive = errors.New("subscribe and publishes are mutually exclusive; one component is one direction")

// gateMessageDirection checks the template's block kind against the
// direction an explicit message flag would wire. Known-kinds mismatch and
// no-messaging kinds are hard errors — a flag that silently vanished
// would leave a record whose wiring contradicts the rendered code. An
// absent or unknown kind stays direction-neutral: today's behavior for
// --subscribe, and the tolerated shape for kind-less message templates.
func gateMessageDirection(tmpl *Template, flagDirection string) error {
	kind := blockKindFromLabels(tmpl.Metadata.Labels)
	dir := MessageDirection(kind)
	switch {
	case dir == flagDirection:
		return nil
	case dir == MessageDirectionNone && kind == BlockKindTransactional:
		return fmt.Errorf("template %q: %w\ntransactional integrations talk with external systems directly and wire no messages", tmpl.Metadata.Name, ErrMessageDirection)
	case dir == MessageDirectionNone:
		return nil // unknown or absent kind: direction-neutral
	case dir == MessageDirectionPublish:
		return fmt.Errorf("template %q: %w\n--subscribe wires a consuming component, but this template publishes messages; use --publishes", tmpl.Metadata.Name, ErrMessageDirection)
	default:
		return fmt.Errorf("template %q: %w\n--publishes wires a producing component, but this template subscribes to messages; use --subscribe", tmpl.Metadata.Name, ErrMessageDirection)
	}
}

// seedMessageParameters seeds every message parameter with the resolved
// message id and rejects a pre-set value naming a different message —
// the same contract both message flags offer: the resolution is the
// parameter's value, a disagreement is a mistake to fix, not to merge. A
// present but non-string value conflicts like a wrong string would: the
// rendered parameter and the block snapshot must never be allowed to
// diverge silently.
//
// A template declaring more than one message parameter is refused under
// the flags: one create wires one message, so which parameter should take
// it is a question the flag cannot answer. The label accepts a comma list
// for template-side rendering; the multi-message wiring is the shape a
// list-shaped flag grows into.
func seedMessageParameters(templateName string, params []string, sets map[string]any, flag string, conflictErr error, message string) error {
	if len(params) > 1 {
		return fmt.Errorf("template %q: %s wires one message, but the manifest declares %d message parameters (%s)", templateName, flag, len(params), strings.Join(params, ", "))
	}
	for _, name := range params {
		value, present := sets[name]
		if !present || isEmpty(value) {
			sets[name] = message
			continue
		}
		if s, ok := value.(string); !ok || s != message {
			return fmt.Errorf("template %q: %w\n%s resolved %q, but %s was set to %q; remove the conflicting value or make them match", templateName, conflictErr, flag, message, name, value)
		}
	}
	return nil
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.io/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.io/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.io/data-flow"

	// TemplateMessageParamsLabel names the manifest label that declares
	// which parameters carry message wiring, as a comma-separated list of
	// parameter names. A template without it declares no message
	// parameters: --subscribe against it is a usage error (R4), and its
	// parameters get no message suggestions however they are named.
	TemplateMessageParamsLabel = "intropy.io/message-params"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"

	// Message direction values, derived from block kind. The mapping is
	// boundary-relative data-flow inverted: an extractor flows data in
	// from the external system and publishes messages, a loader flows out
	// and subscribes. MessageDirection is the one home of that flip.
	MessageDirectionPublish   = "publish"
	MessageDirectionSubscribe = "subscribe"
	MessageDirectionNone      = ""
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.io/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.io/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.io/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

// MessageDirection maps a template's block kind to the direction its
// message parameters wire: publish for producers, subscribe for
// consumers, None for kinds that talk with external systems directly
// (transactional integrations) and for unknown or absent kinds — the
// gate treats those as direction-neutral rather than guessing. A kind
// with no messaging must carry no message parameters for the flags to
// stay coherent; that check lives with the message-parameters gate.
func MessageDirection(kind string) string {
	switch kind {
	case BlockKindExtractor:
		return MessageDirectionPublish
	case BlockKindLoader:
		return MessageDirectionSubscribe
	default:
		return MessageDirectionNone
	}
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

package template

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const testTemplateYAML = `apiVersion: intropy.io/v1
kind: Template
metadata:
  name: test-template
  title: Test
spec:
  parameters:
    type: object
    required: [integrationName]
    properties:
      integrationName:
        type: string
      namespace:
        type: string
        default: default
`

// newTemplateLibrary builds a single-template library laid out as the v1
// model expects: <template>/template.yaml plus <template>/skeleton/<files>.
func newTemplateLibrary(t *testing.T, tag string) *testLibrary {
	t.Helper()
	return newTestLibrary(t, tag, map[string]string{
		"test-template/template.yaml":           testTemplateYAML,
		"test-template/skeleton/README.md.tmpl": "{{ .integrationName }} in {{ .namespace }}\n",
	})
}

func TestCreateWritesOutputJSON(t *testing.T) {
	lib := newTemplateLibrary(t, "v9.9.9")

	outDir := filepath.Join(t.TempDir(), "out")
	jsonPath := filepath.Join(t.TempDir(), "result.json")
	var stderr bytes.Buffer

	err := Create(context.Background(), CreateOptions{
		Template:   "test-template",
		OutputDir:  outDir,
		Version:    "v9.9.9",
		SetValues:  map[string]any{"integrationName": "orders"},
		NoInput:    true,
		OutputJSON: jsonPath,
		Stderr:     &stderr,
		Source:     lib.sourceOpts(t.TempDir(), nil),
	})
	if err != nil {
		t.Fatalf("Create: %v\nstderr: %s", err, stderr.String())
	}

	data, err := os.ReadFile(jsonPath)
	if err != nil {
		t.Fatal(err)
	}
	var got CreateResult
	if err := json.Unmarshal(data, &got); err != nil {
		t.Fatalf("unmarshal result: %v\n%s", err, string(data))
	}
	if got.Template != "test-template" {
		t.Errorf("Template = %q", got.Template)
	}
	if got.Owner != defaultTemplateOwner || got.Repo != defaultTemplateRepo {
		t.Errorf("Owner/Repo = %q/%q, want the resolved defaults", got.Owner, got.Repo)
	}
	if got.Version != "v9.9.9" {
		t.Errorf("Version = %q", got.Version)
	}
	if !filepath.IsAbs(got.OutputDir) {
		t.Errorf("OutputDir should be absolute: %q", got.OutputDir)
	}
	if got.Values["integrationName"] != "orders" {
		t.Errorf("values[integrationName] = %v", got.Values["integrationName"])
	}
	if got.Values["namespace"] != "default" {
		t.Errorf("values[namespace] = %v (default should layer in)", got.Values["namespace"])
	}
}

func TestCreateOnManifestAbortsBeforeOutput(t *testing.T) {
	lib := newTemplateLibrary(t, "v9.9.9")

	outDir := filepath.Join(t.TempDir(), "out")
	var stderr bytes.Buffer
