	}
	systemBefore := readFile(t, filepath.Join(hostDir, "OrderFlowSystem.cs"))

	stdout, stderr, err := runUpdate(t, lib, UpdateOptions{StartDir: ws, DryRun: true, OutputJSON: "-"})
	if err != nil {
		t.Fatalf("Update: %v\nstderr: %s", err, stderr.String())
	}

