	conflicted := filepath.Join(hostDir, "Ports.cs")
	if err := os.WriteFile(conflicted, []byte("// hand-edited\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	recordBefore, err := os.ReadFile(filepath.Join(hostDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
