package system

import (
	"fmt"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// buildPayload assembles the value map passed as SetValues to the
// system-host template. The payload carries workspace facts only — topic and
// port names, component wiring, the detected contracts sibling — and the
// template derives everything that exists only inside the generated
// files: the Topics/Ports field identifiers, the joins between
// components and those fields, and the csproj ProjectReference path.
//
// The contracts sibling travels as a relative include: the template renders
// it verbatim into the host csproj's ProjectReference, and the host is
// always created as a sibling of the contracts project, so the CLI's
// workspace-relative path and the include differ only by the leading "../".
// Computing the include here keeps the templates (and the test fixtures that
// mirror them) free of host-side path arithmetic.
func buildPayload(m *Model, outputDir, kebab string) (map[string]any, error) {
	topics := make([]any, len(m.Topics))
	for i, t := range m.Topics {
		topics[i] = map[string]any{
			"pubsub":   t.Pubsub,
			"name":     t.Name,
			"contract": t.Contract,
		}
	}

	ports := make([]any, len(m.Ports))
	for i, c := range m.Ports {
		ports[i] = map[string]any{
			"name": c.Name,
		}
	}

	components := make([]any, len(m.Components))
	for i, c := range m.Components {
		components[i] = ComponentEntry(c)
	}

	// The internal messagegroup: what the components declare by name,
	// disjoint from the transport list above. Host templates that predate
	// the section ignore the key; message-aware templates render from it.
	messages := make([]any, len(m.Messages))
	for i, msg := range m.Messages {
		e := map[string]any{
			"name": msg.Name,
			"type": msg.Type,
		}
		if msg.Contract != "" {
			e["contract"] = msg.Contract
		}
		if msg.Dataschema != "" {
			e["dataschema"] = msg.Dataschema
		}
		if msg.Publisher != "" {
			e["publisher"] = msg.Publisher
		}
		messages[i] = e
	}

	payload := map[string]any{
		"name":       kebab,
		"topics":     topics,
		"messages":   messages,
		"ports":      ports,
		"components": components,
	}
	if m.Shared != nil {
		include, err := contractsInclude(outputDir, *m.Shared)
		if err != nil {
			return nil, err
		}
		payload["sharedContracts"] = map[string]any{
			"name":    m.Shared.Name,
			"include": include,
		}
	}
	return payload, nil
}

// ComponentEntry is one component's wiring as the system-host template
// consumes it — both in the sys create payload and in the component list
// sys update stores in the host's scaffold record.
//
// Kind is verbatim: Assemble already validated it against the parse
// registry. The wiring fields follow the component's shape, not its kind
// — a topic carries topic, one port port, two ports fromPort/toPort —
// and the template resolves each name to the field identifier it derived
// for the topic or port. The keys match the transactional scaffold
// record's: the template library's system-host reads fromPort/toPort
// (template release v0.4.0+).
func ComponentEntry(c Component) map[string]any {
	entry := map[string]any{
		template.KeyAppID: c.AppID,
		"kind":            c.Kind,
	}
	if c.Topic != nil {
		entry[template.KeyTopic] = map[string]any{
			template.KeyPubsub: c.Topic.Pubsub,
			template.KeyName:   c.Topic.Name,
		}
	}
	if c.Message != nil {
		// The template joins the two message views by name; the direction
		// is already the kind. Dataschema only exists on external snapshots.
		entry[template.KeyMessage] = c.Message.Name
		if c.Message.Dataschema != "" {
			entry[template.KeyDataschema] = c.Message.Dataschema
		}
	}
	switch len(c.Ports) {
	case 0:
	case 1:
		entry[template.KeyPort] = c.Ports[0]
	default:
		entry[template.KeyFromPort] = c.Ports[0]
		entry[template.KeyToPort] = c.Ports[1]
	}
	return entry
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

package system

import (
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project, records
// with a kind in the blockParsers registry become components, and
// everything else is skipped through warnf. The returned model's
// Name/ProjectName/SystemClass are left empty — the caller fills them
// around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components []Component
		shared     []SharedLibrary
		byAppID    = map[string]string{}   // appId -> scaffold dir
		byTopic    = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir   = map[TopicKey]string{} // key -> dir that defined it
		byPort     = map[string]string{}   // port -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := template.RecordValue(e, template.KeyName)
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		}

		parse, ok := blockParsers[e.BlockKind]
		if !ok {
			warnf("skipping %s: unsupported block kind %q (sys create assembles %s)", e.Path, e.BlockKind, strings.Join(supportedKinds(), ", "))
			continue
		}

		appID, err := template.RecordValue(e, template.KeyAppID)
		if err != nil {
			return nil, err
		}
		c := Component{AppID: appID, Kind: e.BlockKind, Path: e.Path}
		if err := parse(e, &c); err != nil {
			return nil, err
		}
		if c.missingPort {
			warnf("%s: scaffold record has no port — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		for _, port := range c.Ports {
			if prev, ok := byPort[port]; ok {
				return nil, fmt.Errorf("duplicate port %q: declared by both %s and %s (each block gets its own port; rename one in the record's values)", port, prev, e.Path)
			}
			byPort[port] = e.Path
		}

		components = append(components, c)
	}

	if err := resolveSubscriptionChannels(components); err != nil {
		return nil, err
	}
	for i := range components {
		c := &components[i]
		if c.Topic == nil {
			continue
		}
		key := *c.Topic
		if seen, ok := byTopic[key]; ok {
			// A block-shaped record may name a channel its contract says
			// nothing about — an external snapshot and a producer on one
			// topic agree without either saying so. Only two non-empty,
			// differing contracts are a real conflict.
			if seen.Contract != "" && c.topicContract != "" && seen.Contract != c.topicContract {
				return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", key.Name, key.Pubsub, seen.Contract, firstDir[key], c.topicContract, c.Path)
			}
			continue
		}
		byTopic[key] = Topic{TopicKey: key, Contract: c.topicContract}
		firstDir[key] = c.Path
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold integrations first ('intropy int create <kind> -n <Name> ...'), then run 'intropy sys create' from the workspace root", ErrNoComponents)
	}
	// Zero shared libraries is a valid workspace: a topic-free system never
	// references contracts, and a topic-bearing one gets them from the host
	// template's dependency. More than one is ambiguity the template cannot
	// resolve, so it stays an error regardless of the system's shape.
	if len(shared) > 1 {
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	ports := make([]Port, 0, len(byPort))
	for name := range byPort {
		ports = append(ports, Port{Name: name})
	}
	sort.Slice(ports, func(i, j int) bool { return ports[i].Name < ports[j].Name })

	model := &Model{Components: components, Topics: topics, Ports: ports, Messages: aggregateMessages(components)}
	if len(shared) == 1 {
		model.Shared = &shared[0]
	}
	return model, nil
}

// resolveSubscriptionChannels gives every component a concrete channel:
// an internal subscription takes its producer's, and a producer without a
// recorded topic defaults to the system pubsub on a topic named after the
// message. Legacy records arrive with their own topic and are untouched.
//
// A half-wired internal subscription — nothing publishes the message — is
// a hard error naming the message and the subscribing record: the system
// would render a loader listening to nothing.
func resolveSubscriptionChannels(components []Component) error {
	type publisher struct {
		key      TopicKey
		contract string
		path     string
		appID    string
	}
	channels := map[string]*publisher{}
	for i := range components {
		c := &components[i]
		if c.Message == nil || c.Message.Kind != MessagePublish || c.Message.Name == "" {
			continue
		}
		if c.Topic == nil {
			// A producer without a recorded topic defaults to the system
			// pubsub on a topic named after the message — the only
			// deterministic channel assembly can make offline, and the one
			// an internal subscriber resolves to in the pass below.
			c.topicContract = c.Message.Contract
			c.Topic = &TopicKey{Pubsub: template.DefaultPubsub, Name: c.Message.Name}
		}
		key := *c.Topic
		if r, ok := channels[c.Message.Name]; ok {
			if r.key != key {
				return fmt.Errorf("message %q is published on conflicting channels: %s on pubsub %q/topic %q (%s) vs pubsub %q/topic %q (%s)",
					c.Message.Name, r.appID, r.key.Pubsub, r.key.Name, r.path, key.Pubsub, key.Name, c.Path)
			}
			if r.contract != "" && c.Message.Contract != "" && r.contract != c.Message.Contract {
				return fmt.Errorf("message %q is published with conflicting contracts: %q (%s) vs %q (%s)",
					c.Message.Name, r.contract, r.path, c.Message.Contract, c.Path)
			}
			continue
		}
		channels[c.Message.Name] = &publisher{key: key, contract: c.Message.Contract, path: c.Path, appID: c.AppID}
	}

	for i := range components {
		c := &components[i]
		if c.Message == nil || c.Message.Kind != MessageSubscribe || c.Message.External || c.Topic != nil {
			continue
		}
		r, ok := channels[c.Message.Name]
		if !ok {
			return fmt.Errorf("message %q is subscribed by %s but no component in this workspace publishes it\ndeclare it with a publishes block in the producing record, or add pubsub/topic to the subscribe block to subscribe externally", c.Message.Name, c.Path)
		}
		c.Topic = &TopicKey{Pubsub: r.key.Pubsub, Name: r.key.Name}
	}
	return nil
}

// aggregateMessages builds the internal messagegroup from the components'
// publish declarations, first seen wins, sorted by name. Subscribers name
// the same message; the subscription is visible through ComponentEntry.
// External publications are excluded: the registry serves their
// definition, and duplicating it here would fork the source of truth.
func aggregateMessages(components []Component) []Message {
	seen := map[string]bool{}
	var out []Message
	for _, c := range components {
		if c.Message == nil || c.Message.Kind != MessagePublish || c.Message.External {
			continue
		}
		m := Message{
			Name:       c.Message.Name,
			Type:       c.Message.Name,
			Contract:   c.Message.Contract,
			Dataschema: c.Message.Dataschema,
			Publisher:  c.AppID,
		}
		if seen[m.Name] {
			continue
		}
		seen[m.Name] = true
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

package system

import (
	"fmt"
	"path/filepath"
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check (topic contract conflicts, port uniqueness)
// stays in Assemble, gated on the component's shape.
type parseBlock func(e template.ScaffoldEntry, c *Component) error

// blockParsers is the set of block kinds Assemble accepts. Records with a
// kind absent from the registry are skipped with a warning naming the
// supported kinds. Adding a kind is a constant, a parser, and an entry here.
var blockParsers = map[string]parseBlock{
	template.BlockKindExtractor:     parseTopicBlock,
	template.BlockKindLoader:        parseTopicBlock,
	template.BlockKindTransactional: parseTransactional,
}

// supportedKinds lists the registry keys sorted, for the unsupported-kind
// warning.
func supportedKinds() []string {
	kinds := make([]string, 0, len(blockParsers))
	for k := range blockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// parseTopicBlock parses the wiring of a topic block (extractor, loader).
// A block-shaped record reads its message wiring from subscribe/publishes
// blocks and its transport from the resolution rules below; a legacy flat
// record keeps the topic+contract pair that always paired the halves.
func parseTopicBlock(e template.ScaffoldEntry, c *Component) error {
	if template.HasMessageBlocks(e.Values) {
		return parseMessageBlocks(e, c)
	}

	// Legacy flat-key record. Directionless: the shared topic key pairs the
	// halves, so the direction comes from the block kind — the same rule
	// the host template applies today — and the message name is the topic
	// name, the only message identity this vocabulary had.
	topic, err := template.RecordValue(e, template.KeyTopic)
	if err != nil {
		return err
	}
	contract, err := template.RecordValue(e, template.KeyContract)
	if err != nil {
		return fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values", err)
	}
	pubsub, err := template.RecordValueDefault(e, template.KeyPubsub, template.DefaultPubsub)
	if err != nil {
		return err
	}
	c.Topic = &TopicKey{Pubsub: pubsub, Name: topic}
	c.topicContract = contract
	c.Message = legacyMessageWiring(c.Kind, topic, contract)

	// No fallback for the port: a default would describe a binding the
	// rendered code doesn't use. A missing key is reported by the caller as
	// a warning; a present one must be a non-empty string.
	if _, ok := e.Values[template.KeyPort]; ok {
		port, err := template.RecordValue(e, template.KeyPort)
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// legacyMessageWiring derives the message view of a legacy record. Both
// halves keep the topic as the channel and its name as the message name:
// resolving a block-shaped subscriber against a legacy producer relies on
// the two name spaces agreeing.
func legacyMessageWiring(kind, topic, contract string) *MessageWiring {
	m := &MessageWiring{Name: topic, Contract: contract}
	switch kind {
	case template.BlockKindExtractor:
		m.Kind = MessagePublish
	case template.BlockKindLoader:
		m.Kind = MessageSubscribe
	}
	return m
}

// parseMessageBlocks parses the block wiring shape: at most one of
// subscribe/publishes — both in one record is a record that contradicts
// itself, never a component with two directions.
func parseMessageBlocks(e template.ScaffoldEntry, c *Component) error {
	sub, err := template.ReadSubscribeBlock(e)
	if err != nil {
		return err
	}
	pub, err := template.ReadPublishesBlock(e)
	if err != nil {
		return err
	}
	if sub != nil && pub != nil {
		return fmt.Errorf("%s carries both a subscribe and a publishes block; one component is one direction — keep the publish in its producing record and the subscribe in its consuming record", recordRef(e))
	}
	// A half-wired snapshot is a broken record in either direction: topic
	// without pubsub and pubsub without topic both name a channel the
	// system cannot assemble, and silently dropping the recorded half
	// would fabricate a different one.
	if pub != nil && pub.Pubsub != "" && pub.Topic == "" {
		_, err := blockRequiredField(e, template.KeyPublishes, template.KeyTopic, template.KeyPubsub, pub.Topic)
		return err
	}
	switch {
	case pub != nil:
		c.Message = &MessageWiring{Kind: MessagePublish, Name: pub.Message, Contract: pub.Contract, Dataschema: pub.Dataschema, External: pub.External()}
		// A registry-resolved publication carries its channel snapshot: the
		// recorded channel wins exactly as a legacy record's does, and the
		// message stays out of the internal messagegroup (the registry
		// already serves its definition). An internal publication defaults
		// to the system pubsub on a topic named after the message.
		if pub.External() {
			pubsub, err := blockRequiredField(e, template.KeyPublishes, template.KeyPubsub, template.KeyTopic, pub.Pubsub)
			if err != nil {
				return err
			}
			c.Topic = &TopicKey{Pubsub: pubsub, Name: pub.Topic}
		}
		// The topic entry carries this contract whether the channel was
		// recorded or defaulted — without it, two producers on one channel
		// could disagree on the contract and dress the disagreement up as
		// two unrelated topic entries.
		c.topicContract = pub.Contract
	case sub != nil:
		c.Message = &MessageWiring{Kind: MessageSubscribe, Name: sub.Message, Dataschema: sub.Dataschema}
		c.Message.External = sub.External()
		if sub.External() {
			pubsub, err := blockRequiredField(e, template.KeySubscribe, template.KeyPubsub, template.KeyTopic, sub.Pubsub)
			if err != nil {
				return err
			}
			c.Topic = &TopicKey{Pubsub: pubsub, Name: sub.Topic}
		}
	}

	// A port carries over from any shape: block writers emit it like the
	// flat writers did.
	if _, ok := e.Values[template.KeyPort]; ok {
		port, err := template.RecordValue(e, template.KeyPort)
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// blockRequiredField re-reports an empty required snapshot half as the
// paired-field error, naming both keys so the fix is one edit away.
func blockRequiredField(e template.ScaffoldEntry, block, key, triggerKey, value string) (string, error) {
	if value != "" {
		return value, nil
	}
	return "", fmt.Errorf("%s: values.%s.%s is required when values.%s.%s is set", recordRef(e), block, key, block, triggerKey)
}

// recordRef names the record the way parse errors across assembly do.
func recordRef(e template.ScaffoldEntry) string {
	return filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
}

// parseTransactional parses the wiring of a transactional block: exactly
// two ports, From before To, and no topic. Both ports are required — a
// half-wired transactional block would render broken code.
func parseTransactional(e template.ScaffoldEntry, c *Component) error {
	from, err := template.RecordValue(e, template.KeyFromPort)
	if err != nil {
		return err
	}
	to, err := template.RecordValue(e, template.KeyToPort)
	if err != nil {
		return err
	}
	c.Ports = []string{from, to}
	return nil
}

