// The direction gate: --subscribe against the real extractor and --publishes
// against the real loader are usage errors, and nothing lands on disk.
// A template flag that silently vanished would leave a record whose wiring
// contradicts the rendered code.
func TestRealManifestDirectionGates(t *testing.T) {
	src := realTemplatesSource(t)
	bases := map[string]map[string]any{
		"extractor": {"name": "OrderSweep", "organization": "Maxbo", "topic": "orders", "contract": "Order"},
		"loader":    {"name": "OrderFileLoader", "organization": "Maxbo", "topic": "orders", "contract": "Order"},
	}
	runs := []struct {
		tmpl  string
		block *SubscribeBlock
		pub   *PublishesBlock
		tmpl2 string
		block2 *SubscribeBlock
		pub2  *PublishesBlock
	}{
		{tmpl: "extractor", block: subscribeFixture(), tmpl2: "loader", pub2: publishesFixture()},
	}
	_ = bases
	for _, r := range runs {
		for _, c := range []struct {
			tmpl  string
			block *SubscribeBlock
			pub   *PublishesBlock
			hint  string
		}{
			{r.tmpl, r.block, r.pub, "use --publishes"},
			{r.tmpl2, r.block2, r.pub2, "use --subscribe"},
		} {
			outDir := filepath.Join(t.TempDir(), "out")
			var stderr bytes.Buffer
			err := Create(context.Background(), CreateOptions{
				Template:  c.tmpl,
				OutputDir: outDir,
				NoInput:   true,
				Stderr:    &stderr,
				Source:    src,
				SetValues: bases[c.tmpl],
				Subscribe: c.block,
				Publishes: c.pub,
			})
			if !strings.Contains(err.Error(), ErrMessageDirection.Error()) {
				t.Fatalf("%s: err = %v, want %v", c.tmpl, err, ErrMessageDirection)
			}
			if !strings.Contains(err.Error(), c.hint) {
				t.Errorf("%s: error %q should suggest %q", c.tmpl, err, c.hint)
			}
			if _, statErr := os.Stat(filepath.Join(outDir, ScaffoldRelPath)); !os.IsNotExist(statErr) {
				t.Errorf("%s: a gate refusal must not write a scaffold record (stat err = %v)", c.tmpl, statErr)
			}
		}
	}
}

